package com.tnr.cityguide.notification;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notifications") public class Notification {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="user_id",nullable=false) private UUID userId;@Column(nullable=false,length=20) private String category;@Column(nullable=false,length=120) private String title;@Column(nullable=false,length=1000) private String message;@Column(name="target_url",length=500) private String targetUrl;@Column(name="read_at") private Instant readAt;@Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();}
 public UUID getId(){return id;}public UUID getUserId(){return userId;}public void setUserId(UUID v){userId=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public String getTargetUrl(){return targetUrl;}public void setTargetUrl(String v){targetUrl=v;}public Instant getReadAt(){return readAt;}public void setReadAt(Instant v){readAt=v;}public Instant getCreatedAt(){return createdAt;}
}